Checkout shows $1,250.00 for an item priced $12.50 when a 0% discount code is applied. Without a code it shows $12.50 correctly.

```javascript
function toCents(dollars) {
  return Math.round(dollars * 100);
}

function formatPrice(cents) {
  return '$' + (cents / 100).toLocaleString('en-US', { minimumFractionDigits: 2 });
}

function applyDiscount(priceCents, percent) {
  const discounted = priceCents * (1 - percent / 100);
  return toCents(discounted);
}

function checkoutTotal(item, code) {
  let cents = toCents(item.price);
  if (code) {
    cents = applyDiscount(cents, code.percent);
  }
  return formatPrice(cents);
}

console.log(checkoutTotal({ price: 12.5 }, { percent: 0 }));
```

