Each blog post should carry only its own tags, but the third post printed below shows tags from the first two posts as well.

```python
def add_tag(tag, tags=[]):
    if tag not in tags:
        tags.append(tag)
    return tags

def build_post(title, raw_tags):
    tags = None
    for t in raw_tags.split(','):
        tags = add_tag(t.strip())
    return {'title': title, 'tags': tags or []}

posts = [
    build_post('Intro', 'python, basics'),
    build_post('Async', 'python, asyncio'),
    build_post('Release notes', 'news'),
]
print(posts[2])
# {'title': 'Release notes', 'tags': ['python', 'basics', 'asyncio', 'news']}
```

